def transform(grid):
    """Draw an outward square spiral from 3, stopping when it encounters a 2."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    starts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 3]
    if not starts:
        return out
    r, c = starts[0]
    dirs = [(-1, 0), (0, 1), (1, 0), (0, -1)]
    length = 2
    step_no = 0
    for _ in range(200):
        dr, dc = dirs[step_no % 4]
        for _ in range(length):
            r += dr
            c += dc
            if 0 <= r < h and 0 <= c < w:
                if grid[r][c] == 2:
                    return out
                out[r][c] = 3
        step_no += 1
        if step_no % 2 == 0:
            length += 2
        if r < -h or r > 2*h or c < -w or c > 2*w:
            break
    return out
